const run = (program, args) => {
  try { execFileSync(program, args, { cwd: root, stdio: 'inherit' }); }
  catch { throw new Error(`Cannot build catalog or WASM: ${program} ${args.join(' ')} failed. Install Rust, wasm32-unknown-unknown and wasm-pack.`); }
};
run('cargo', ['run', '--quiet', '--manifest-path', 'crates/catalog_tool/Cargo.toml', '--', 'init']);
await mkdir(join(out, 'data'), { recursive: true });
run('cargo', ['run', '--quiet', '--manifest-path', 'crates/catalog_tool/Cargo.toml', '--', 'export-public', '--out', join(out, 'data', 'catalog.json')]);
const publicCatalog = JSON.parse(await readFile(join(out, 'data', 'catalog.json'), 'utf8'));
const publicCultivars = new Map(publicCatalog.cultivars.map(cultivar => [cultivar.slug, cultivar]));
const isCurrent = value => value && Number.isFinite(Date.parse(String(value).replace(' ', 'T') + 'Z')) && Date.parse(String(value).replace(' ', 'T') + 'Z') > Date.now();
const safeMerchantUrl = value => {
  try { const url = new URL(value); return url.protocol === 'https:' && !url.username && !url.password ? url.href : null; }
  catch { return null; }
};
function withCommerce(html, variety) {
  const row = publicCultivars.get(variety.slug);
  if (!row) return html;
  const offers = (row.offers || []).filter(offer => offer.kind === 'affiliate' && offer.checked_at && isCurrent(offer.expires_at) && safeMerchantUrl(offer.destination_url));
  const batches = (row.own_batches || []).filter(batch => batch.plant_stage === 'sale_ready' && batch.quantity_available > 0 && batch.checked_at && isCurrent(batch.expires_at));
  if (!offers.length && !batches.length) return html;
  const offerCards = offers.map(offer => `<article class="commerce-card"><span class="eyebrow">ПАРТНЁРСКОЕ ПРЕДЛОЖЕНИЕ</span><h3>${e(offer.product_name)}</h3><p>Продавец: ${e(offer.seller_name)}. Проверено: ${e(offer.checked_at.slice(0, 10))}.</p>${offer.price_minor != null && offer.currency === 'RUB' ? `<p>Цена при проверке: ${e(new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB' }).format(offer.price_minor / 100))}</p>` : ''}<a class="btn btn-dark" href="${e(safeMerchantUrl(offer.destination_url))}" target="_blank" rel="sponsored noopener noreferrer" data-affiliate-offer="${e(offer.id)}" data-cultivar="${e(variety.slug)}">Перейти к продавцу ${arrow}</a><small>Партнёрская ссылка. Цена и наличие могут измениться на сайте продавца.</small></article>`).join('');
  const batchCards = batches.map(batch => `<article class="commerce-card"><span class="eyebrow">СОБСТВЕННАЯ ПАРТИЯ</span><h3>Партия ${e(batch.batch_code)}</h3><p>${e(batch.provenance_summary)}</p><p>Готовых растений: ${e(batch.quantity_available)}. Получение: ${e(batch.pickup_locality)}, ${e(batch.pickup_region_name)}.</p><p>${e(batch.pickup_terms)}</p><small>Проверено: ${e(batch.checked_at.slice(0, 10))}.</small></article>`).join('');
  const section = `<section class="section wrap commerce-section"><span class="eyebrow">РЕАЛЬНЫЕ ПРЕДЛОЖЕНИЯ</span><h2>Где получить саженец</h2><div class="commerce-grid">${offerCards}${batchCards}</div></section>`;
  return html.replace('</main>', `${section}</main>`).replace('Проверенных предложений на сайте пока нет.', 'Проверенные предложения показаны ниже.');
}

function withEvidence(html, variety) {
  const row = publicCultivars.get(variety.slug);
  const section = evidenceSection(row) + admissionSection(row);
  return section ? html.replace('<section class="section wrap source-panel">', `${section}<section class="section wrap source-panel">`) : html;
}

function withCultivarReviews(html, variety) {
  return html.replace('</head>', '<script defer src="/assets/reviews.js"></script></head>').replace('</main>', `${cultivarReviews(variety)}</main>`);
}

const lotChecklist = layout({ title: 'Проверить документы на партию саженцев', description: 'Практический список документов для проверки происхождения и состояния партии малины или клубники перед покупкой.', path: '/proverka-partii/', active: 'guide', script: '/assets/lot-checklist.js', body: `<section class="simple-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span><a href="/in-vitro/">Посадочный материал</a><span> / </span>Проверка партии</div><span class="eyebrow">ИНСТРУМЕНТ / ПОСАДОЧНЫЙ МАТЕРИАЛ</span><h1>Проверьте<br><em>партию.</em></h1><p>Соберите вопросы к поставщику до покупки. Чеклист помогает проверить документы и условия хранения; он не удостоверяет сорт, здоровье растений или будущий урожай.</p></div></section><section class="section wrap" id="lot-checklist"><div class="lot-checklist-panel"><label class="lot-kind-label" for="planting-stock">Тип посадочного материала</label><select id="planting-stock" name="planting-stock"><option value="frigo">Земляника садовая Frigo</option><option value="tissue">Микрорастения после In Vitro</option><option value="other">Другой тип растений</option></select><h2>Документы и сведения о партии</h2><p>Попросите связать каждый документ с названием сорта и конкретной партией, которую вам отправят.</p><fieldset class="lot-checks"><legend>Для любой партии</legend><label><input type="checkbox"><span>Название сорта, поставщик, номер партии и дата отгрузки указаны вместе.</span></label><label><input type="checkbox"><span>Указаны тип растения, способ размножения и стадия доращивания.</span></label><label><input type="checkbox"><span>Есть документы о происхождении маточного материала и сортовой идентичности.</span></label><label><input type="checkbox"><span>Фитосанитарный документ называет проверенные организмы, метод, лабораторию, дату, образец и связь образца с партией.</span></label><label><input type="checkbox"><span>Есть письменные требования поставщика к перевозке, хранению и сроку посадки.</span></label></fieldset><fieldset class="lot-checks" data-stock-kind="frigo"><legend>Дополнительно для Frigo</legend><label><input type="checkbox"><span>Поставщик объяснил, что означает заявленный класс и по какому стандарту он определён.</span></label><label><input type="checkbox"><span>Если для заявленного срока урожая важна индукция цветочной почки, поставщик указал её статус и основание.</span></label><label><input type="checkbox"><span>Есть прослеживаемые сведения о температуре хранения и перевозки до передачи партии.</span></label></fieldset><fieldset class="lot-checks" data-stock-kind="tissue" hidden><legend>Дополнительно для растений после In Vitro</legend><label><input type="checkbox"><span>Указаны лаборатория, дата выхода из стерильной культуры и этап адаптации Ex Vitro.</span></label><label><input type="checkbox"><span>Результаты фитосанитарных тестов относятся к исходной партии/маточнику и перечисляют конкретные тесты.</span></label><label><input type="checkbox"><span>Поставщик дал условия адаптации, упаковки и перехода к открытому воздуху.</span></label></fieldset><fieldset class="lot-checks" data-stock-kind="other" hidden><legend>Уточните для выбранного формата</legend><label><input type="checkbox"><span>Получена спецификация именно этого формата растения и требований к его посадке.</span></label><label><input type="checkbox"><span>Состояние корней и надземной части описано для партии до отгрузки.</span></label><label><input type="checkbox"><span>Поставщик письменно обозначил допустимый срок и режим хранения.</span></label></fieldset><p id="checklist-status" class="lot-checklist-status" role="status" aria-live="polite"></p><p class="lot-checklist-limit">Отрицательный результат одного теста относится только к указанному организму, образцу, методу и дате. Формулировки «без вирусов» или «In Vitro — значит здоровый» без документов на конкретную партию не подтверждены.</p><a class="btn btn-outline" href="/in-vitro/">Как читать сведения об In Vitro ${arrow}</a></div><aside class="lot-checklist-sources"><span class="eyebrow">ОСНОВАНИЯ</span><h2>Проверяйте связь документа с растением</h2><p>Культура тканей описывает способ размножения. Диагностика и сортовая идентичность требуют отдельных методов и записей.</p><a href="https://fps.ucdavis.edu/strawberry.cfm" target="_blank" rel="noopener noreferrer">UC Davis Foundation Plant Services · земляника ↗</a><a href="https://californiaagriculture.org/api/v1/articles/112420-meristem-culture-for-elimination-of-strawberry-viruses.pdf" target="_blank" rel="noopener noreferrer">California Agriculture · сочетание меристемы и термообработки ↗</a></aside></section>` });

const plantingCalculator = layout({
  title: 'Калькулятор саженцев малины и клубники — сколько нужно для грядки',
  description: 'Рассчитайте количество саженцев по размерам грядки, числу рядов и выбранным расстояниям. Формула и допущения открыты; схема посадки задаётся вами.',
  path: '/instrumenty/raschet-sazhencev/',
  script: '<script type="module" src="/assets/planting.js"></script>',
  body: `<section class="simple-hero planting-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span>Расчёт саженцев</div><span class="eyebrow">СХЕМА ПОСАДКИ / ГЕОМЕТРИЯ</span><h1>Сколько саженцев<br><em>поместится?</em></h1><p>Укажите размеры и расстояния для вашей схемы. Мы посчитаем место, а выбор шага посадки оставим вам и проверенному источнику по культуре.</p></div></section>
  <section class="section wrap planting-layout"><div class="planting-form-panel"><span class="eyebrow">01 / ВАШИ РАЗМЕРЫ</span><h2>План грядки</h2><form id="planting-form"><div class="planting-fields"><label>Длина одной грядки, м<input name="length" type="number" inputmode="decimal" min="0.01" max="10000" step="any" placeholder="Например, 10" required></label><label>Ширина одной грядки, м<input name="width" type="number" inputmode="decimal" min="0.01" max="1000" step="any" placeholder="Например, 1" required></label><label>Число одинаковых грядок<input name="beds" type="number" inputmode="numeric" min="1" max="10000" step="1" value="1" required></label><label>Между рядами, см<input name="rowSpacing" type="number" inputmode="decimal" min="0.01" max="100000" step="any" placeholder="Укажите ваш шаг" required></label><label>Между растениями в ряду, см<input name="plantSpacing" type="number" inputmode="decimal" min="0.01" max="100000" step="any" placeholder="Укажите ваш шаг" required></label></div><button class="btn btn-dark" type="submit">Посчитать ${arrow}</button></form><div id="planting-result" class="planting-result" role="status" aria-live="polite" tabindex="-1" hidden></div></div><aside class="planting-method"><span class="eyebrow">02 / КАК СЧИТАЕМ</span><h2>Прозрачная формула</h2><p>Для прямых параллельных рядов: число рядов = целая часть от ширины грядки ÷ междурядье. Растений в ряду = целая часть от длины грядки ÷ шага между растениями. Итог — произведение этих чисел на количество грядок.</p><p>Первое растение и первый ряд стоят на расстоянии половины шага от края; неполные интервалы не считаем. Проходы, края участка, шахматную посадку и потери саженцев в расчёт не включаем.</p><p>Это геометрия, а не агрономическая рекомендация. Подходящие расстояния зависят от культуры, сорта, способа выращивания и ухода; урожайность по этой формуле не определяется.</p><a class="text-link" href="/podbor/">После расчёта — выбрать сорт ↗</a></aside></section>`
});

const pruningHelper = layout({
  title: 'Как обрезать малину — схема для летнего и ремонтантного сорта',
  description: 'Помощник по обрезке малины: определите тип плодоношения и цель сбора, узнайте какие побеги сохранить и когда их обрезать. Источники и ограничения.',
  path: '/instrumenty/obrezka-maliny/',
  script: '<script type="module" src="/assets/pruning.js"></script>',
  body: `<section class="simple-hero pruning-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span><a href="/malina/">Малина</a><span> / </span>Обрезка</div><span class="eyebrow">ИНСТРУМЕНТ / СХЕМА ОБРЕЗКИ</span><h1>Какие побеги<br><em>оставить?</em></h1><p>Выберите тип малины и цель урожая. Покажем порядок действий, не подменяя местные сроки чужим календарём.</p></div></section>
  <section class="section wrap pruning-layout"><div class="pruning-main"><span class="eyebrow">01 / ПРОВЕРЬТЕ СОРТ</span><h2>Сначала тип плодоношения</h2><p>Летняя малина плодоносит на побегах прошлого года. Ремонтантная может дать урожай на побегах текущего года. Если тип неизвестен, не выбирайте схему наугад.</p><form id="pruning-form"><fieldset class="pruning-options"><legend>Что известно о сорте?</legend><label><input type="radio" name="type" value="unknown" checked><span><strong>Пока не знаю</strong><small>Есть куст, но нет проверенного названия и описания.</small></span></label><label><input type="radio" name="type" value="summer"><span><strong>Летняя малина</strong><small>Урожай на перезимовавших побегах прошлого года.</small></span></label><label><input type="radio" name="type" value="primocane"><span><strong>Ремонтантная малина</strong><small>Поздний урожай на побегах текущего года.</small></span></label></fieldset><fieldset id="pruning-harvest" class="pruning-options pruning-harvest" hidden disabled><legend>Какой режим сбора вы хотите?</legend><label><input type="radio" name="harvest" value="single" checked><span><strong>Один поздний урожай</strong><small>Простая схема для ремонтантной малины.</small></span></label><label><input type="radio" name="harvest" value="double"><span><strong>Два урожая</strong><small>Только для сильных, хорошо укоренившихся растений.</small></span></label></fieldset><button class="btn btn-dark" type="submit">Показать схему ${arrow}</button></form><div id="pruning-result" class="pruning-result" role="status" aria-live="polite" tabindex="-1" hidden></div></div><aside class="pruning-aside"><span class="eyebrow">02 / НЕ ОШИБИТЕСЬ</span><h2>Что сохранять</h2><div class="pruning-cane-guide"><div><b>Летняя</b><p>Молодые побеги текущего года — основа следующего летнего сбора.</p></div><div><b>Ремонтантная</b><p>Новые побеги могут дать поздний урожай в этом же сезоне.</p></div></div><p>В этом инструменте нет определения сорта по фото и нет прогноза вызревания для конкретного региона России.</p><a class="text-link" href="/sorta/?crop=raspberry">Проверить сорт в каталоге ↗</a></aside></section>
  <section class="section wrap pruning-basis"><span class="eyebrow">ИСТОЧНИК И ГРАНИЦЫ</span><h2>На чём основана схема</h2><p>Раздел <a href="https://www.rhs.org.uk/fruit/raspberries/grow-your-own" target="_blank" rel="noopener noreferrer">RHS · Pruning and Training ↗</a> описывает разные схемы для летней и плодоносящей на побегах текущего года малины. Мы проверили его 26.09.2026. Сроки RHS относятся к условиям Великобритании: для России ориентируйтесь на состояние растений, погоду и проверенные местные сведения. Название сорта и тип плодоношения уточняйте по надёжному описанию и документам посадочного материала.</p><p>Для подробностей: <a href="/zhurnal/obrezka-letney-maliny/">летняя малина</a> · <a href="/zhurnal/obrezka-remontantnoy-maliny/">ремонтантная малина</a> · <a href="/zhurnal/letnyaya-ili-remontantnaya-malina/">как отличить типы</a>.</p><a class="text-link" href="/instrumenty/raschet-sazhencev/">Следующий шаг: рассчитать посадку ↗</a></section>`
});

const rating = layout({ title: 'Рейтинг сортов малины и клубники — рекомендации садоводов', description: 'Какие сорта малины и клубники рекомендуют читатели. Голосование, число рекомендаций и прозрачная методика рейтинга.', path: '/rating/', active: 'rating', body: ratingBody(varieties, voteSnapshot, voteApiUrl) });
const pages = new Map([['/', home], ['/malina/', withCropReading(cropPage('raspberry'), 'raspberry')], ['/klubnika/', withCropReading(cropPage('strawberry'), 'strawberry')], ['/sorta/', catalog], ['/sravnenie/malina/', raspberryComparison], ['/sravnenie/klubnika/', strawberryComparison], ['/rating/', rating], ['/podbor/', pickerPage], ['/instrumenty/raschet-sazhencev/', plantingCalculator], ['/instrumenty/obrezka-maliny/', pruningHelper], ...cities.map(city => [`/podbor/${city.slug}/`, cityPickerPage(city)]), ['/otzyvy/', reviews], ['/goroda/', cityDirectory], ['/guide/', guide], ['/in-vitro/', inVitro], ['/proverka-partii/', lotChecklist], ['/about/', about], ['/zhurnal/', articleCollection()], ['/zhurnal/malina/', articleCollection('raspberry')], ['/zhurnal/klubnika/', articleCollection('strawberry')], ...varieties.map(v => [`/sorta/${v.slug}/`, withCultivarReviews(withCommerce(withEvidence(withCropReading(varietyPage(v), v.cropKey), v), v), v)]), ...articles.map(article => [articlePath(article), articlePage(article)])]);
for (const [path, html] of pages) { const dir = join(out, path); await mkdir(dir, { recursive: true }); await writeFile(join(dir, 'index.html'), withSiteBase(html)); }
await mkdir(join(out, 'assets'), { recursive: true });
await writeFile(join(out, 'assets', 'site.css'), withCssBase(await readFile(join(root, 'site', 'assets', 'site.css'), 'utf8')));
for (const asset of ['site.js', 'votes.js', 'picker-compare.js', 'vote-model.js', 'verified-selector.js', 'reviews.js', 'review-geo.js', 'cities.js', 'comparison.js', 'comparison-model.mjs', 'lot-checklist.js', 'planting.js', 'planting-model.mjs', 'pruning.js', 'pruning-model.mjs', 'favicon.svg', 'berries-hero.webp', 'raspberry-garden.webp', 'strawberry-garden.webp', 'raspberry-mark.webp', 'strawberry-mark.webp', ...new Set(articles.flatMap(article => [article.heroImage?.file, ...article.sections.map(section => section.image?.file)].filter(Boolean))), ...Object.values(varietyMedia).map(image => image.file)]) await copyFile(join(root, 'site', 'assets', asset), join(out, 'assets', asset));
await copyFile(join(root, 'db', 'public', 'reviews.json'), join(out, 'data', 'reviews.json'));
await writeFile(join(out, 'data', 'votes.json'), JSON.stringify(voteSnapshot) + '\n');
run('wasm-pack', ['build', 'crates/selector', '--target', 'web', '--release', '--out-dir', 'pkg']);
await mkdir(join(out, 'assets', 'selector'), { recursive: true });
for (const asset of ['malina_selector.js', 'malina_selector_bg.wasm']) await copyFile(join(root, 'crates', 'selector', 'pkg', asset), join(out, 'assets', 'selector', asset));
await writeFile(join(out, 'robots.txt'), `User-agent: *\nAllow: /\n${siteUrl ? `Sitemap: ${siteUrl}/sitemap.xml\n` : ''}`);
if (siteUrl) await writeFile(join(out, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${paths.map(path => `<url><loc>${siteUrl}${path}</loc></url>`).join('')}</urlset>`);
if (siteUrl) {
  const items = articles.map(article => {
    const publishedIso = article.publishedIso ?? editorialReviewedIso;
    const image = article.heroImage?.file ?? `${article.crop === 'raspberry' ? 'raspberry' : 'strawberry'}-garden.webp`;
    const imageDescription = article.heroImage?.caption ?? 'Иллюстрация культуры, созданная для сайта генератором изображений; не фотография сорта.';
    return `<item><title>${e(article.title)}</title><link>${e(siteUrl + articlePath(article))}</link><guid isPermaLink="true">${e(siteUrl + articlePath(article))}</guid><description>${e(article.lead)}</description><pubDate>${new Date(`${publishedIso}T00:00:00Z`).toUTCString()}</pubDate><media:content url="${e(`${siteUrl}/assets/${image}`)}" medium="image" type="image/webp"/><media:description>${e(imageDescription)}</media:description></item>`;
  }).join('');
  await writeFile(join(out, 'feed.xml'), `<?xml version="1.0" encoding="UTF-8"?><rss version="2.0" xmlns:media="http://search.yahoo.com/mrss/"><channel><title>Ягодный журнал МАЛИНА — КЛУБНИКА</title><link>${e(siteUrl + '/zhurnal/')}</link><description>Проверяемые материалы о выборе и выращивании малины и садовой земляники.</description><language>ru</language><lastBuildDate>${new Date().toUTCString()}</lastBuildDate>${items}</channel></rss>`);
}
console.log(`Built ${pages.size} HTML pages${siteUrl ? ` for ${siteUrl}` : ''}.`);
